import java.io.*;
import java.util.*;
import java.text.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String[]> records = new ArrayList<>();
        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;
        boolean first = true;
        while ((line = br.readLine()) != null) {
            if (first) {
                first = false;
                continue;
            }
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(",");
            records.add(parts);
        }
        br.close();

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCounts = new TreeMap<>();
        String highestName = "";
        double highestSalary = Double.NEGATIVE_INFINITY;
        double totalBudget = 0;

        for (String[] r : records) {
            String name = r[1].trim();
            String department = r[2].trim();
            double salary = Double.parseDouble(r[3].trim());

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCounts.merge(department, 1, Integer::sum);

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }

            totalBudget += salary;
        }

        DecimalFormat avgFmt = new DecimalFormat("#,##0.00");
        DecimalFormat intFmt = new DecimalFormat("#,##0");

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");
        for (Map.Entry<String, List<Double>> e : deptSalaries.entrySet()) {
            List<Double> salaries = e.getValue();
            double avg = salaries.stream().mapToDouble(Double::doubleValue).average().orElse(0);
            sb.append(String.format("  %s: $%s%n", e.getKey(), avgFmt.format(avg)));
        }
        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%s)%n", highestName, intFmt.format(Math.round(highestSalary))));
        sb.append("\n");
        sb.append("Departments with >2 employees:\n");
        for (Map.Entry<String, Integer> e : deptCounts.entrySet()) {
            if (e.getValue() > 2) {
                sb.append(String.format("  %s (%d employees)%n", e.getKey(), e.getValue()));
            }
        }
        sb.append("\n");
        sb.append(String.format("Total Budget: $%s%n", intFmt.format(Math.round(totalBudget))));

        System.out.print(sb.toString());
    }
}

