let filePath = "<tmp>"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
var lines = content.components(separatedBy: "\n").map { $0.replacingOccurrences(of: "\r", with: "") }.filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let dataLines = Array(lines.dropFirst())

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []

for line in dataLines {
    let fields = line.components(separatedBy: ",")
    if fields.count >= 6 {
        let name = fields[1].trimmingCharacters(in: .whitespaces)
        let department = fields[2].trimmingCharacters(in: .whitespaces)
        let salaryStr = fields[3].trimmingCharacters(in: .whitespaces).replacingOccurrences(of: "$", with: "").replacingOccurrences(of: ",", with: "")
        let salary = Double(salaryStr) ?? 0
        employees.append(Employee(name: name, department: department, salary: salary))
    }
}

func formatInt(_ value: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    formatter.maximumFractionDigits = 0
    formatter.minimumFractionDigits = 0
    return formatter.string(from: NSNumber(value: value)) ?? "\(value)"
}

func formatDouble(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    formatter.maximumFractionDigits = 2
    formatter.minimumFractionDigits = 2
    return formatter.string(from: NSNumber(value: value)) ?? String(format: "%.2f", value)
}

