import * as fs from 'fs';

const filePath = '<tmp>';
const content = fs.readFileSync(filePath, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

const regex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

const levelCounts: Record<string, number> = {};
const componentErrorCounts: Record<string, number> = {};
const errorMessages: Set<string> = new Set();
const hourCounts: Record<string, number> = {};

for (const line of lines) {
  const match = line.match(regex);
  if (!match) continue;

  const timestamp = match[1];
  const level = match[2];
  const component = match[3];
  const message = match[4];

  levelCounts[level] = (levelCounts[level] || 0) + 1;

  if (level === 'ERROR') {
    componentErrorCounts[component] = (componentErrorCounts[component] || 0) + 1;
    errorMessages.add(message);
  }

  const hour = timestamp.split(' ')[1].substring(0, 2);
  hourCounts[hour] = (hourCounts[hour] || 0) + 1;
}

let out = '';
out += '=== Log Analysis ===\n';
out += '\n';
out += 'Entries by Level:\n';
const sortedLevels = Object.keys(levelCounts).sort();
for (const level of sortedLevels) {
  out += `  ${level}: ${levelCounts[level]}\n`;
}
out += '\n';

let maxErrors = 0;
let topComponent = '';
const sortedComponents = Object.keys(componentErrorCounts).sort();
for (const comp of sortedComponents) {
  if (componentErrorCounts[comp] > maxErrors) {
    maxErrors = componentErrorCounts[comp];
    topComponent = comp;
  }
}
out += `Component with Most Errors: ${topComponent} (${maxErrors} errors)\n`;
out += '\n';

out += 'Unique Error Messages:\n';
const sortedMessages = Array.from(errorMessages).sort();
for (const msg of sortedMessages) {
  out += `  - ${msg}\n`;
}
out += '\n';

let maxEntries = 0;
let busiestHour = '';
const sortedHours = Object.keys(hourCounts).sort();
for (const h of sortedHours) {
  if (hourCounts[h] > maxEntries) {
    maxEntries = hourCounts[h];
    busiestHour = h;
  }
}
out += `Busiest Hour: ${busiestHour}:00 (${maxEntries} entries)\n`;

process.stdout.write(out);

