use std::collections::HashMap;
use std::fs;

fn format_commas(n: i64) -> String {
    let negative = n < 0;
    let abs = if negative { -n } else { n };
    let s = abs.to_string();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (s.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if negative {
        format!("-{}", result)
    } else {
        result
    }
}

fn format_commas_2dp(n: f64) -> String {
    let negative = n < 0.0;
    let abs = if negative { -n } else { n };
    let int_part = abs as i64;
    let dec_part = ((abs - int_part as f64) * 100.0).round() as i64;
    let int_str = format_commas(int_part);
    if negative {
        format!("-{}.{:02}", int_str, dec_part)
    } else {
        format!("{}.{:02}", int_str, dec_part)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_sum: HashMap<String, f64> = HashMap::new();
    let mut dept_count: HashMap<String, i64> = HashMap::new();
    let mut highest_name = String::new();
    let mut highest_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|f| f.trim()).collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        *dept_sum.entry(department.clone()).or_insert(0.0) += salary;
        *dept_count.entry(department.clone()).or_insert(0) += 1;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }

        total_budget += salary;
    }

    let mut depts: Vec<&String> = dept_sum.keys().collect();
    depts.sort();

    print!("=== Salary Report ===\n");
    print!("\n");
    print!("Average Salary by Department:\n");
    for dept in &depts {
        let sum = dept_sum[*dept];
        let count = dept_count[*dept];
        let avg = sum / count as f64;
        print!("  {}: ${}\n", dept, format_commas_2dp(avg));
    }
    print!("\n");
    print!("Highest Paid: {} (${})\n", highest_name, format_commas(highest_salary as i64));
    print!("\n");
    print!("Departments with >2 employees:\n");
    let mut filtered: Vec<(&String, &i64)> = dept_count.iter()
        .filter(|(_, &c)| c > 2)
        .collect();
    filtered.sort_by(|a, b| a.0.cmp(b.0));
    for (dept, &count) in &filtered {
        print!("  {} ({} employees)\n", dept, count);
    }
    print!("\n");
    print!("Total Budget: ${}\n", format_commas(total_budget as i64));
}

