import Foundation

let filePath = "<tmp>"

guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)) else {
    FileHandle.standardError.write("Could not read file\n".data(using: .utf8)!)
    exit(1)
}

let json = try! JSONSerialization.jsonObject(with: data) as! [String: Any]

let nodes = json["nodes"] as! [String]
let edges = json["edges"] as! [[String: Any]]

var adj: [String: [(String, Double)]] = [:]
for node in nodes {
    adj[node] = []
}

for edge in edges {
    let from = edge["from"] as! String
    let to = edge["to"] as! String
    let weight = (edge["weight"] as! NSNumber).doubleValue

    adj[from]?.append((to, weight))
    adj[to]?.append((from, weight))
}

var dist: [String: Double] = [:]
var visited: Set<String> = []

for node in nodes {
    dist[node] = Double.greatestFiniteMagnitude
}
dist["A"] = 0

while visited.count < nodes.count {
    var minNode: String? = nil
    var minDist = Double.greatestFiniteMagnitude

    for node in nodes {
        if !visited.contains(node) && (dist[node] ?? Double.greatestFiniteMagnitude) < minDist {
            minDist = dist[node]!
            minNode = node
        }
    }

    guard let current = minNode else { break }
    visited.insert(current)

    if let neighbors = adj[current] {
        for (neighbor, weight) in neighbors {
            if !visited.contains(neighbor) {
                let newDist = dist[current]! + weight
                if newDist < (dist[neighbor] ?? Double.greatestFiniteMagnitude) {
                    dist[neighbor] = newDist
                }
            }
        }
    }
}

print("=== Shortest Paths from A ===")
print("")

let sortedNodes = nodes.sorted()
for node in sortedNodes {
    let d = dist[node] ?? Double.greatestFiniteMagnitude
    if d == Double.greatestFiniteMagnitude {
        print("A -> \(node): unreachable")
    } else if d == 0 {
        print("A -> \(node): 0")
    } else if d == floor(d) {
        print("A -> \(node): \(Int(d))")
    } else {
        print("A -> \(node): \(d)")
    }
}

