    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();

        List<String[]> products = new ArrayList<>();

        int idx = 0;
        while (idx < json.length()) {
            int start = json.indexOf('{', idx);
            if (start == -1) break;
            int depth = 0;
            int end = start;
            while (end < json.length()) {
                char c = json.charAt(end);
                if (c == '{') depth++;
                else if (c == '}') {
                    depth--;
                    if (depth == 0) break;
                }
                end++;
            }
            String obj = json.substring(start, end + 1);
            String name = extractString(obj, "name");
            double price = extractNumber(obj, "price");
            products.add(new String[]{name, String.valueOf(price)});
            idx = end + 1;
        }

        List<String[]> filtered = new ArrayList<>();
        double total = 0.0;
        for (String[] p : products) {
            double price = Double.parseDouble(p[1]);
            if (price > 50.00) {
                filtered.add(p);
                total += price;
            }
        }

        filtered.sort((a, b) -> a[0].compareTo(b[0]));

        System.out.print("=== Filtered Products (price > $50.00) ===\n");
        System.out.print("\n");
        for (String[] p : filtered) {
            double price = Double.parseDouble(p[1]);
            System.out.printf("%s: $%.2f\n", p[0], price);
        }
        System.out.print("\n");
        System.out.printf("Count: %d\n", filtered.size());
        System.out.printf("Total: $%.2f\n", total);
    }

    private static String extractString(String json, String key) {
        String pattern = "\"" + key + "\"\\s*:\\s*\"";
        Matcher m = Pattern.compile(pattern).matcher(json);
        if (m.find()) {
            int start = m.end();
            int end = start;
            while (end < json.length()) {
                if (json.charAt(end) == '\\' && end + 1 < json.length()) {
                    end += 2;
                    continue;
                }
                if (json.charAt(end) == '"') break;
                end++;
            }
            return json.substring(start, end);
        }
        return "";
    }

    private static double extractNumber(String json, String key) {
        String pattern = "\"" + key + "\"\\s*:\\s*";
        Matcher m = Pattern.compile(pattern).matcher(json);
        if (m.find()) {
            int start = m.end();
            int end = start;
            while (end < json.length()) {
                char c = json.charAt(end);
                if (Character.isDigit(c) || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E') {
                    end++;
                } else {
                    break;
                }
            }
            return Double.parseDouble(json.substring(start, end));
        }
        return 0.0;
    }
}

