    if n.is_nan() {
        "null".to_string()
    } else if n.is_infinite() {
        "null".to_string()
    } else if n.fract() == 0.0 && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn serialize_json(val: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match val {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => format_number(*n),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let items: Vec<String> = arr
                    .iter()
                    .map(|v| format!("{}{}", pad_inner, serialize_json(v, indent + 1)))
                    .collect();
                format!("[\n{}\n{}]", items.join(",\n"), pad)
            }
        }
        Json::Object(map) => {
            if map.is_empty() {
                "{}".to_string()
            } else {
                let items: Vec<String> = map
                    .iter()
                    .map(|(k, v)| {
                        format!(
                            "{}\"{}\": {}",
                            pad_inner,
                            escape_string(k),
                            serialize_json(v, indent + 1)
                        )
                    })
                    .collect();
                format!("{{\n{}\n{}}}", items.join(",\n"), pad)
            }
        }
    }
}

fn merge(a: &Json, b: &Json) -> Json {
    match (a, b) {
        (Json::Object(a_map), Json::Object(b_map)) => {
            let mut result = BTreeMap::new();
            for (k, v) in a_map {
                result.insert(k.clone(), v.clone());
