    while (*p && *p != '[') p++;
    if (*p == '[') p++;

    while (*p) {
        /* skip whitespace */
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
        if (*p == ']') break;
        if (*p != '{') { p++; continue; }
        p++; /* skip { */

        /* Find matching } (no nesting expected for flat objects) */
        const char *obj_start = p;
        int depth = 1;
        while (*p && depth > 0) {
            if (*p == '{') depth++;
            else if (*p == '}') depth--;
            if (depth > 0) p++;
        }
        /* p is now at } or NUL */
        size_t obj_len = (size_t)(p - obj_start);
        const char *obj_end = (*p == '}') ? p + 1 : p;

        /* Extract fields within this object */
        char *obj_copy = malloc(obj_len + 1);
        if (!obj_copy) {
            perror("malloc");
            free(buf);
            free(products);
            return 1;
        }
        memcpy(obj_copy, obj_start, obj_len);
        obj_copy[obj_len] = '\0';

        char *name = extract_string_field(obj_copy, "name");
        double price = extract_number_field(obj_copy, "price");
        free(obj_copy);

        if (name && price > 50.00) {
            if (count >= max_products) {
                max_products *= 2;
                Product *tmp = realloc(products, max_products * sizeof(Product));
                if (!tmp) {
                    perror("realloc");
                    free(name);
                    free(buf);
                    free(products);
                    return 1;
                }
                products = tmp;
            }
            products[count].name = name;
            products[count].price = price;
            count++;
        } else {
            free(name);
        }

        if (*p == '}') p++;
        /* skip whitespace */
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
        if (*p == ',') { p++; continue; }
        if (*p == ']') break;
    }

    free(buf);

    /* Sort by name ascending */
    qsort(products, count, sizeof(Product), compare_products);

    /* Print output */
    printf("=== Filtered Products (price > $50.00) ===\n");
    printf("\n");
    for (size_t i = 0; i < count; i++) {
        printf("%s: $%.2f\n", products[i].name, products[i].price);
    }
    printf("\n");
    printf("Count: %zu\n", count);
    double total_price = 0.0;
    for (size_t i = 0; i < count; i++) {
        total_price += products[i].price;
    }
    printf("Total: $%.2f\n", total_price);

    for (size_t i = 0; i < count; i++) {
        free(products[i].name);
    }
    free(products);
    return 0;
}
