static char *run_cmd(const char *cmd)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;

    size_t cap = 4096;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    for (;;) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) {
                pclose(fp);
                free(buf);
                return NULL;
            }
            buf = tmp;
        }
        size_t n = fread(buf + len, 1, cap - len - 1, fp);
        if (n == 0)
            break;
        len += n;
    }
    buf[len] = '\0';
    pclose(fp);

    while (len > 0 &&
           (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
            buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

int main(void)
{
    char *hostname = run_cmd("hostname");
    char *os       = run_cmd("uname -s");
    char *arch     = run_cmd("uname -m");
    char *username = run_cmd("whoami");

    if (!hostname) hostname = (char *)"";
    if (!os)       os       = (char *)"";
    if (!arch)     arch     = (char *)"";
    if (!username) username = (char *)"";

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    free(hostname);
    free(os);
    free(arch);
    free(username);

    return 0;
}

