        int totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<String[]>> entry : extToFiles.entrySet()) {
            String ext = entry.getKey();
            List<String[]> files = entry.getValue();

            files.sort((a, b) -> a[0].compareTo(b[0]));

            int extFileCount = files.size();
            int extLines = 0;
            long extChars = 0;

            for (String[] f : files) {
                extLines += Integer.parseInt(f[1]);
                extChars += Long.parseLong(f[2]);
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(extFileCount).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (String[] f : files) {
                sb.append("    ").append(f[0]).append(": ").append(f[1]).append(" lines, ").append(f[2]).append(" chars\n");
            }

            totalFiles += extFileCount;
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static void walk(Path dir, Path root, Map<String, List<String[]>> extToFiles, Set<Path> visited) throws IOException {
        Path realDir;
        try {
            realDir = dir.toRealPath();
        } catch (IOException e) {
            return;
        }
        if (!visited.add(realDir)) return;

        File[] children = dir.toFile().listFiles();
        if (children == null) return;

        for (File file : children) {
            Path filePath = file.toPath();

            if (Files.isSymbolicLink(filePath)) {
                continue;
            }

            if (Files.isDirectory(filePath)) {
                walk(filePath, root, extToFiles, visited);
            } else if (Files.isRegularFile(filePath)) {
                String relPath = root.relativize(filePath).toString().replace(File.separatorChar, '/');

                int lines = countLines(filePath);
                long chars = Files.size(filePath);

                String fileName = filePath.getFileName().toString();
                String ext;
                int dotIdx = fileName.lastIndexOf('.');
                if (dotIdx > 0) {
                    ext = fileName.substring(dotIdx);
                } else {
                    ext = "(no extension)";
                }

                extToFiles.computeIfAbsent(ext, k -> new ArrayList<>())
                        .add(new String[]{relPath, String.valueOf(lines), String.valueOf(chars)});
            }
        }
    }

    static int countLines(Path path) throws IOException {
        byte[] data = Files.readAllBytes(path);
        if (data.length == 0) return 0;
        int count = 0;
        for (byte b : data) {
            if (b == '\n') count++;
        }
        if (data[data.length - 1] != '\n') count++;
        return count;
    }
}

