        int[][] A = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int[][] B = {{9, 8, 7}, {6, 5, 4}, {3, 2, 1}};

        int n = 3;
        int[][] C = new int[n][n];

        // Matrix multiplication C = A x B
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                C[i][j] = 0;
                for (int k = 0; k < n; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }

        // Determinant of 3x3 matrix
        int det = C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1])
                - C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0])
