use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn count_lines_and_chars(path: &Path) -> (usize, usize) {
    let mut content = Vec::new();
    if let Ok(mut f) = fs::File::open(path) {
        let _ = f.read_to_end(&mut content);
    }

    let chars = content.len();
    let mut lines = 0;
    if !content.is_empty() {
        lines = content.iter().filter(|&&b| b == b'\n').count();
        if content[content.len() - 1] != b'\n' {
            lines += 1;
        }
    }

    (lines, chars)
}

fn get_extension(path: &Path) -> String {
    match path.extension() {
        Some(ext) => format!(".{}", ext.to_string_lossy()),
        None => String::new(),
    }
}

fn walk(
    dir: &Path,
    root: &Path,
    files_by_ext: &mut BTreeMap<String, Vec<(String, usize, usize)>>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(&path, root, files_by_ext);
        } else if path.is_file() {
            let (lines, chars) = count_lines_and_chars(&path);
            let rel_path = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .to_string();
            let ext = get_extension(&path);

            files_by_ext
                .entry(ext)
                .or_default()
                .push((rel_path, lines, chars));
        }
    }
}

fn main() {
    let root = Path::new(
        "<tmp>",
    );

    let mut files_by_ext: BTreeMap<String, Vec<(String, usize, usize)>> = BTreeMap::new();

    walk(root, root, &mut files_by_ext);

    for files in files_by_ext.values_mut() {
        files.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0usize;
    let mut total_lines = 0usize;
    let mut total_chars = 0usize;

    for (ext, files) in &files_by_ext {
        let n = files.len();
        let lines: usize = files.iter().map(|f| f.1).sum();
        let chars: usize = files.iter().map(|f| f.2).sum();

        total_files += n;
        total_lines += lines;
        total_chars += chars;

        println!("Extension: {}", ext);
        println!("  Files: {}", n);
        println!("  Total Lines: {}", lines);
        println!("  Total Characters: {}", chars);

        for (path, lines, chars) in files {
            println!("    {}: {} lines, {} chars", path, lines, chars);
        }
    }

    println!();
    println!(
        "Total: {} files, {} lines, {} characters",
        total_files, total_lines, total_chars
    );
}

