import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function walkDir(dir: string, root: string, visited: Set<string>): FileInfo[] {
  const results: FileInfo[] = [];

  let realDir: string;
  try {
    realDir = fs.realpathSync(dir);
  } catch {
    return results;
  }

  if (visited.has(realDir)) return results;
  visited.add(realDir);

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      const subResults = walkDir(fullPath, root, visited);
      results.push(...subResults);
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      let lines = 0;
      let chars = 0;
      try {
        const buffer = fs.readFileSync(fullPath);
        chars = buffer.length;
        const content = buffer.toString('utf-8');
        const linesArr = content.split('\n');
        if (linesArr[linesArr.length - 1] === '') {
          linesArr.pop();
        }
        lines = linesArr.length;
      } catch {
        lines = 0;
        chars = 0;
      }
      results.push({ relativePath, lines, chars });
    }
  }

  return results;
}

const allFiles = walkDir(rootDir, rootDir, new Set());

const groups = new Map<string, FileInfo[]>();
for (const file of allFiles) {
  const ext = path.extname(file.relativePath);
  if (!groups.has(ext)) {
    groups.set(ext, []);
  }
  groups.get(ext)!.push(file);
}

const sortedExts = Array.from(groups.keys()).sort();

for (const ext of sortedExts) {
  groups.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
}

let output = '=== File Tree Analysis ===\n';
output += '\n';

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of sortedExts) {
  const files = groups.get(ext)!;
  const extTotalLines = files.reduce((sum, f) => sum + f.lines, 0);
  const extTotalChars = files.reduce((sum, f) => sum + f.chars, 0);

  output += `Extension: ${ext}\n`;
  output += `  Files: ${files.length}\n`;
  output += `  Total Lines: ${extTotalLines}\n`;
  output += `  Total Characters: ${extTotalChars}\n`;

  for (const file of files) {
    output += `    ${file.relativePath}: ${file.lines} lines, ${file.chars} chars\n`;
  }

  totalFiles += files.length;
  totalLines += extTotalLines;
  totalChars += extTotalChars;
}

output += '\n';
output += `Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

process.stdout.write(output);

