use std::collections::{BinaryHeap, HashMap};
use std::cmp::Ordering;
use std::fs;

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len() && self.data[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        assert_eq!(self.next(), Some(c), "expected '{}'", c);
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        let c = self.peek().unwrap();
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => Json::Str(self.parse_string()),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut entries = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(entries);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse();
            entries.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("expected ',' or '}' in object"),
            }
        }
        Json::Object(entries)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(items);
        }
        loop {
            let val = self.parse();
            items.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("expected ',' or ']' in array"),
            }
        }
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{08}'),
                        Some('f') => s.push('\u{0c}'),
                        Some('u') => {
                            let mut code: u32 = 0;
                            for _ in 0..4 {
                                let c = self.next().unwrap();
                                code = code * 16 + c.to_digit(16).unwrap() as u32;
                            }
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => panic!("bad escape sequence"),
                    }
                }
                Some(c) => s.push(c),
                None => panic!("unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.data[start..self.pos].iter().collect();
        Json::Number(s.parse::<f64>().unwrap())
    }

    fn parse_bool(&mut self) -> Json {
        if self.data[self.pos] == 't' {
            self.pos += 4;
            Json::Bool(true)
        } else {
            self.pos += 5;
            Json::Bool(false)
        }
    }

    fn parse_null(&mut self) -> Json {
        self.pos += 4;
        Json::Null
    }
}

#[derive(Clone, Eq, PartialEq)]
struct HeapItem {
    dist: f64,
    node: String,
}

impl Ord for HeapItem {
    fn cmp(&self, other: &Self) -> Ordering {
        other.dist.partial_cmp(&self.dist).unwrap()
    }
}

impl PartialOrd for HeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn fmt_num(v: f64) -> String {
    if v == v as i64 as f64 {
        format!("{}", v as i64)
    } else {
        format!("{}", v)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");
    let mut parser = Parser::new(&content);
    let json = parser.parse();

    let (nodes, edges) = match &json {
        Json::Object(entries) => {
            let mut nodes: Vec<String> = Vec::new();
            let mut edges: Vec<(String, String, f64)> = Vec::new();
            for (key, val) in entries {
                match key.as_str() {
                    "nodes" => {
                        if let Json::Array(arr) = val {
                            for item in arr {
                                if let Json::Str(s) = item {
                                    nodes.push(s.clone());
                                }
                            }
                        }
                    }
                    "edges" => {
                        if let Json::Array(arr) = val {
                            for item in arr {
                                if let Json::Object(e) = item {
                                    let mut from = String::new();
                                    let mut to = String::new();
                                    let mut weight = 0.0f64;
                                    for (k, v) in e {
                                        match k.as_str() {
                                            "from" => {
                                                if let Json::Str(s) = v {
                                                    from = s.clone();
                                                }
                                            }
                                            "to" => {
                                                if let Json::Str(s) = v {
                                                    to = s.clone();
                                                }
                                            }
                                            "weight" => {
                                                if let Json::Number(n) = v {
                                                    weight = *n;
                                                }
                                            }
                                            _ => {}
                                        }
                                    }
                                    edges.push((from, to, weight));
                                }
                            }
                        }
                    }
                    _ => {}
                }
            }
            (nodes, edges)
        }
        _ => panic!("Expected JSON object at top level"),
    };

    // Build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).insert(Vec::new());
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_default().push((to.clone(), *weight));
        adj.entry(to.clone()).or_default().push((from.clone(), *weight));
    }

    // Dijkstra's algorithm from "A"
    let source = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
    }
    dist.insert(source.clone(), 0.0);

    let mut heap: BinaryHeap<HeapItem> = BinaryHeap::new();
    heap.push(HeapItem { dist: 0.0, node: source.clone() });

    while let Some(HeapItem { dist: d, node }) = heap.pop() {
        if d > dist.get(&node).copied().unwrap_or(f64::INFINITY) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, weight) in neighbors {
                let new_dist = d + weight;
                let current = dist.get(neighbor).copied().unwrap_or(f64::INFINITY);
                if new_dist < current {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(HeapItem { dist: new_dist, node: neighbor.clone() });
                }
            }
        }
    }

    // Collect and sort node names alphabetically
    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    // Output
    println!("=== Shortest Paths from A ===");
    println!();
    for node in &sorted_nodes {
        let d = dist.get(*node).copied().unwrap_or(f64::INFINITY);
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", node);
        } else {
            println!("A -> {}: {}", node, fmt_num(d));
        }
    }
}

