import Foundation

let baseDir = "<tmp>"
let fm = FileManager.default

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var groups: [String: [FileInfo]] = [:]
var visitedDirs = Set<String>()

func walk(_ path: String) {
    if visitedDirs.contains(path) { return }
    visitedDirs.insert(path)

    let dirURL = URL(fileURLWithPath: path)
    let keys: [URLResourceKey] = [.isRegularFileKey, .isSymbolicLinkKey, .isDirectoryKey]
    guard let contents = try? fm.contentsOfDirectory(at: dirURL, includingPropertiesForKeys: keys, options: []) else { return }

    for url in contents {
        let vals = try? url.resourceValues(forKeys: Set(keys))
        let isSymlink = vals?.isSymbolicLink ?? false
        if isSymlink { continue }

        let isFile = vals?.isRegularFile ?? false
        let isDir = vals?.isDirectory ?? false

        if isFile {
            let fullPath = url.path
            let relPath = String(fullPath.dropFirst(baseDir.count + 1))
            var lines = 0
            var chars = 0
            if let data = try? Data(contentsOf: url) {
                chars = data.count
                if !data.isEmpty {
                    let nlCount = data.reduce(0) { $0 + ($1 == 10 ? 1 : 0) }
                    lines = (data.last == 10) ? nlCount : nlCount + 1
                }
            }
            let ext = url.pathExtension
            let extKey = ext.isEmpty ? "" : "." + ext
            groups[extKey, default: []].append(FileInfo(relativePath: relPath, lines: lines, chars: chars))
        } else if isDir {
            walk(url.path)
        }
    }
}

walk(baseDir)

print("=== File Tree Analysis ===")
print("")

