var totalLines = 0
var totalChars = 0

let sortedExts = groups.keys.sorted()

for ext in sortedExts {
    let fileInfos = groups[ext]!.sorted { $0.relativePath < $1.relativePath }
    let nFiles = fileInfos.count
    let nLines = fileInfos.reduce(0) { $0 + $1.lines }
    let nChars = fileInfos.reduce(0) { $0 + $1.chars }

