import Foundation

let baseDir = "<tmp>"
let fm = FileManager.default

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var groups: [String: [FileInfo]] = [:]
var visitedDirs = Set<String>()

func walk(_ path: String, relPrefix: String) {
    if visitedDirs.contains(path) { return }
    visitedDirs.insert(path)

    let dirURL = URL(fileURLWithPath: path)
    let keys: [URLResourceKey] = [.isRegularFileKey, .isSymbolicLinkKey, .isDirectoryKey]
    guard let contents = try? fm.contentsOfDirectory(at: dirURL, includingPropertiesForKeys: keys, options: []) else { return }

    for url in contents {
        let vals = try? url.resourceValues(forKeys: Set(keys))
        let isSymlink = vals?.isSymbolicLink ?? false
        if isSymlink { continue }

        let isFile = vals?.isRegularFile ?? false
        let isDir = vals?.isDirectory ?? false

        if isFile {
            let name = url.lastPathComponent
            let relPath = relPrefix.isEmpty ? name : relPrefix + "/" + name
            var lines = 0
            var chars = 0
            if let data = try? Data(contentsOf: url) {
                chars = data.count
                if !data.isEmpty {
                    let nlCount = data.reduce(0) { $0 + ($1 == 10 ? 1 : 0) }
                    lines = (data.last == 10) ? nlCount : nlCount + 1
                }
            }
            let ext = url.pathExtension
            let extKey = ext.isEmpty ? "" : "." + ext
            groups[extKey, default: []].append(FileInfo(relativePath: relPath, lines: lines, chars: chars))
        } else if isDir {
            let name = url.lastPathComponent
            let newPrefix = relPrefix.isEmpty ? name : relPrefix + "/" + name
            walk(url.path, relPrefix: newPrefix)
        }
    }
}

walk(baseDir, relPrefix: "")

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

let sortedExts = groups.keys.sorted()

for ext in sortedExts {
    let fileInfos = groups[ext]!.sorted { $0.relativePath < $1.relativePath }
    let nFiles = fileInfos.count
    let nLines = fileInfos.reduce(0) { $0 + $1.lines }
    let nChars = fileInfos.reduce(0) { $0 + $1.chars }

    totalFiles += nFiles
    totalLines += nLines
    totalChars += nChars

    print("Extension: \(ext)")
    print("  Files: \(nFiles)")
    print("  Total Lines: \(nLines)")
    print("  Total Characters: \(nChars)")
    for fi in fileInfos {
        print("    \(fi.relativePath): \(fi.lines) lines, \(fi.chars) chars")
    }
