struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        self.parse_value()
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.pos += 4;
                Json::Bool(true)
            }
            Some('f') => {
                self.pos += 5;
                Json::Bool(false)
            }
            Some('n') => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.next();
        let mut fields = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(fields);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next();
            let val = self.parse_value();
            fields.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Json::Object(fields)
    }

    fn parse_array(&mut self) -> Json {
        self.next();
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => break,
            }
        }
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.next();
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('u') => {
                        let mut hex = String::new();
                        for _ in 0..4 {
                            if let Some(c) = self.next() {
                                hex.push(c);
                            }
                        }
                        let code = u32::from_str_radix(&hex, 16).unwrap_or(0);
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => {}
                },
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let mut s = String::new();
        if self.peek() == Some('-') {
            s.push('-');
            self.pos += 1;
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        Json::Number(s.parse::<f64>().unwrap_or(0.0))
    }
}

fn get_field<'a>(obj: &'a Json, key: &str) -> Option<&'a Json> {
    if let Json::Object(fields) = obj {
        for (k, v) in fields {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

