#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value {
    json_type type;
    int boolean;
    double num_val;
    char *num_str;
    char *str_val;
    struct json_value **items;
    int item_count;
    int item_cap;
    char **keys;
    struct json_value **values;
    int key_count;
    int key_cap;
} json_value;

static json_value *json_new(json_type t) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = t;
    return v;
}

static void json_free(json_value *v) {
    if (!v) return;
    if (v->type == JSON_STRING) free(v->str_val);
    if (v->type == JSON_NUMBER) free(v->num_str);
    if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->item_count; i++) json_free(v->items[i]);
        free(v->items);
    }
    if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->key_count; i++) {
            free(v->keys[i]);
            json_free(v->values[i]);
        }
        free(v->keys);
        free(v->values);
    }
    free(v);
}

static void json_obj_add(json_value *obj, char *key, json_value *val) {
    if (obj->key_count >= obj->key_cap) {
        obj->key_cap = obj->key_cap ? obj->key_cap * 2 : 8;
        obj->keys = (char **)realloc(obj->keys, obj->key_cap * sizeof(char *));
        obj->values = (json_value **)realloc(obj->values, obj->key_cap * sizeof(json_value *));
    }
    obj->keys[obj->key_count] = key;
    obj->values[obj->key_count] = val;
    obj->key_count++;
}

static void json_arr_add(json_value *arr, json_value *val) {
    if (arr->item_count >= arr->item_cap) {
        arr->item_cap = arr->item_cap ? arr->item_cap * 2 : 8;
        arr->items = (json_value **)realloc(arr->items, arr->item_cap * sizeof(json_value *));
    }
    arr->items[arr->item_count] = val;
    arr->item_count++;
}

/* Parser */
static const char *p;

static void skip_ws(void) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
}

static char *parse_string_raw(void) {
    /* assumes *p == '"' */
    p++; /* skip opening quote */
    size_t cap = 64, len = 0;
    char *buf = (char *)malloc(cap);
    while (*p && *p != '"') {
        if (len + 8 >= cap) {
            cap *= 2;
            buf = (char *)realloc(buf, cap);
        }
        if (*p == '\\') {
            p++;
            switch (*p) {
                case '"': buf[len++] = '"'; p++; break;
                case '\\': buf[len++] = '\\'; p++; break;
                case '/': buf[len++] = '/'; p++; break;
                case 'b': buf[len++] = '\b'; p++; break;
                case 'f': buf[len++] = '\f'; p++; break;
                case 'n': buf[len++] = '\n'; p++; break;
                case 'r': buf[len++] = '\r'; p++; break;
                case 't': buf[len++] = '\t'; p++; break;
                case 'u': {
                    p++;
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) {
                        cp <<= 4;
                        if (*p >= '0' && *p <= '9') cp |= *p - '0';
                        else if (*p >= 'a' && *p <= 'f') cp |= *p - 'a' + 10;
                        else if (*p >= 'A' && *p <= 'F') cp |= *p - 'A' + 10;
                        else cp |= 0;
                        p++;
                    }
                    /* Encode as UTF-8 */
                    if (cp < 0x80) {
                        buf[len++] = (char)cp;
                    } else if (cp < 0x800) {
                        if (len + 3 >= cap) { cap *= 2; buf = (char *)realloc(buf, cap); }
                        buf[len++] = (char)(0xC0 | (cp >> 6));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; buf = (char *)realloc(buf, cap); }
                        buf[len++] = (char)(0xE0 | (cp >> 12));
                        buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default:
                    if (len + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, cap); }
                    buf[len++] = *p;
                    p++;
                    break;
            }
        } else {
            buf[len++] = *p;
            p++;
        }
    }
    if (*p == '"') p++;
    if (len + 1 >= cap) { cap = len + 1; buf = (char *)realloc(buf, cap); }
    buf[len] = '\0';
    return buf;
}

static json_value *parse_value(void);

static json_value *parse_object(void) {
    /* assumes *p == '{' */
    p++;
    json_value *obj = json_new(JSON_OBJECT);
    skip_ws();
    if (*p == '}') { p++; return obj; }
    while (1) {
        skip_ws();
        if (*p != '"') break;
        char *key = parse_string_raw();
        skip_ws();
        if (*p != ':') { free(key); break; }
        p++;
        skip_ws();
        json_value *val = parse_value();
        json_obj_add(obj, key, val);
        skip_ws();
        if (*p == ',') { p++; continue; }
        if (*p == '}') { p++; break; }
        break;
    }
    return obj;
}

static json_value *parse_array(void) {
    /* assumes *p == '[' */
    p++;
    json_value *arr = json_new(JSON_ARRAY);
    skip_ws();
    if (*p == ']') { p++; return arr; }
    while (1) {
        skip_ws();
        json_value *val = parse_value();
        json_arr_add(arr, val);
        skip_ws();
        if (*p == ',') { p++; continue; }
        if (*p == ']') { p++; break; }
        break;
    }
    return arr;
}

static json_value *parse_number(void) {
    const char *start = p;
    if (*p == '-') p++;
    while (*p >= '0' && *p <= '9') p++;
    int is_float = 0;
    if (*p == '.') { is_float = 1; p++; while (*p >= '0' && *p <= '9') p++; }
    if (*p == 'e' || *p == 'E') { is_float = 1; p++; if (*p == '+' || *p == '-') p++; while (*p >= '0' && *p <= '9') p++; }
    size_t len = (size_t)(p - start);
    char *num_str = (char *)malloc(len + 1);
    memcpy(num_str, start, len);
    num_str[len] = '\0';
    json_value *v = json_new(JSON_NUMBER);
    v->num_val = strtod(num_str, NULL);
    v->num_str = num_str;
    (void)is_float;
    return v;
}

static json_value *parse_literal(void) {
    if (strncmp(p, "true", 4) == 0) {
