    if (*p == 'e' || *p == 'E') { p++; if (*p == '+' || *p == '-') p++; while (*p >= '0' && *p <= '9') p++; }
    size_t len = (size_t)(p - start);
    char *num_str = (char *)malloc(len + 1);
    memcpy(num_str, start, len);
    num_str[len] = '\0';
    json_value *v = json_new(JSON_NUMBER);
    v->num_val = strtod(num_str, NULL);
    v->num_str = num_str;
    return v;
}

static json_value *parse_literal(void) {
    if (strncmp(p, "true", 4) == 0) {
        p += 4;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 1;
        return v;
    } else if (strncmp(p, "false", 5) == 0) {
        p += 5;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 0;
        return v;
    } else if (strncmp(p, "null", 4) == 0) {
        p += 4;
        return json_new(JSON_NULL);
    }
    return json_new(JSON_NULL);
}

static json_value *parse_value(void) {
    skip_ws();
    if (*p == '{') return parse_object();
    if (*p == '[') return parse_array();
    if (*p == '"') {
        json_value *v = json_new(JSON_STRING);
        v->str_val = parse_string_raw();
        return v;
    }
    if (*p == '-' || (*p >= '0' && *p <= '9')) return parse_number();
    return parse_literal();
}

static json_value *parse_json(const char *text) {
    p = text;
    json_value *v = parse_value();
    return v;
}

/* Serializer */
static void print_escaped_string(const char *s, FILE *f) {
    fputc('"', f);
    for (const char *c = s; *c; c++) {
        unsigned char ch = (unsigned char)*c;
        switch (ch) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (ch < 0x20) fprintf(f, "\\u%04x", ch);
                else fputc(ch, f);
                break;
        }
    }
    fputc('"', f);
}

static void print_value(json_value *v, int indent, FILE *f) {
    int sp = indent * 2;
    switch (v->type) {
        case JSON_NULL:
            fputs("null", f);
            break;
        case JSON_BOOL:
            fputs(v->boolean ? "true" : "false", f);
            break;
        case JSON_NUMBER:
            fputs(v->num_str, f);
            break;
        case JSON_STRING:
            print_escaped_string(v->str_val, f);
            break;
        case JSON_ARRAY:
            if (v->item_count == 0) { fputs("[]", f); break; }
            fputs("[\n", f);
            for (int i = 0; i < v->item_count; i++) {
                for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                print_value(v->items[i], indent + 1, f);
                if (i < v->item_count - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (int j = 0; j < sp; j++) fputc(' ', f);
            fputc(']', f);
            break;
        case JSON_OBJECT: {
            if (v->key_count == 0) { fputs("{}", f); break; }
            int *idx = (int *)malloc(v->key_count * sizeof(int));
            for (int i = 0; i < v->key_count; i++) idx[i] = i;
            for (int i = 1; i < v->key_count; i++) {
                int key_idx = idx[i];
                int j = i - 1;
                while (j >= 0 && strcmp(v->keys[idx[j]], v->keys[key_idx]) > 0) {
                    idx[j + 1] = idx[j];
                    j--;
                }
                idx[j + 1] = key_idx;
            }
            fputs("{\n", f);
            for (int i = 0; i < v->key_count; i++) {
                int ki = idx[i];
                for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                print_escaped_string(v->keys[ki], f);
                fputs(": ", f);
                print_value(v->values[ki], indent + 1, f);
                if (i < v->key_count - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (int j = 0; j < sp; j++) fputc(' ', f);
            fputc('}', f);
            free(idx);
            break;
        }
    }
}

/* Deep equality for dedup */
static int json_equal(json_value *a, json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->num_val == b->num_val;
        case JSON_STRING: return strcmp(a->str_val, b->str_val) == 0;
        case JSON_ARRAY: {
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++)
                if (!json_equal(a->items[i], b->items[i])) return 0;
            return 1;
        }
        case JSON_OBJECT: {
            if (a->key_count != b->key_count) return 0;
            for (int i = 0; i < a->key_count; i++) {
                int found = 0;
                for (int j = 0; j < b->key_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equal(a->values[i], b->values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
        }
    }
    return 0;
}

/* Deep merge: returns a NEW fully independent merged value */
static json_value *deep_merge(json_value *a, json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new(JSON_OBJECT);
        for (int i = 0; i < a->key_count; i++) {
            char *key_copy = (char *)malloc(strlen(a->keys[i]) + 1);
            strcpy(key_copy, a->keys[i]);
            json_obj_add(result, key_copy, deep_copy(a->values[i]));
        }
        for (int i = 0; i < b->key_count; i++) {
            int found = -1;
            for (int j = 0; j < result->key_count; j++) {
                if (strcmp(result->keys[j], b->keys[i]) == 0) { found = j; break; }
            }
            if (found >= 0) {
                json_value *merged = deep_merge(result->values[found], b->values[i]);
                json_free(result->values[found]);
                result->values[found] = merged;
            } else {
                char *key_copy = (char *)malloc(strlen(b->keys[i]) + 1);
                strcpy(key_copy, b->keys[i]);
                json_obj_add(result, key_copy, deep_copy(b->values[i]));
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new(JSON_ARRAY);
        for (int i = 0; i < a->item_count; i++)
            json_arr_add(result, deep_copy(a->items[i]));
        for (int i = 0; i < b->item_count; i++) {
            int dup = 0;
            for (int j = 0; j < result->item_count; j++) {
                if (json_equal(result->items[j], b->items[i])) { dup = 1; break; }
            }
            if (!dup) json_arr_add(result, deep_copy(b->items[i]));
        }
        return result;
    }
    return deep_copy(b);
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    *out_len = rd;
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    size_t len_a, len_b;
    char *text_a = read_file(path_a, &len_a);
    char *text_b = read_file(path_b, &len_b);

    json_value *a = parse_json(text_a);
    json_value *b = parse_json(text_b);

    json_value *merged = deep_merge(a, b);

    print_value(merged, 0, stdout);
    fputc('\n', stdout);

    json_free(merged);
    json_free(a);
    json_free(b);
    free(text_a);
    free(text_b);
    return 0;
}
