#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>

typedef struct {
    char *relpath;
    char *ext;
    long lines;
    long chars;
} FileEntry;

typedef struct {
    FileEntry *entries;
    int count;
    int capacity;
} FileList;

static void add_entry(FileList *list, const char *relpath, const char *ext, long lines, long chars) {
    if (list->count >= list->capacity) {
        int newcap = list->capacity ? list->capacity * 2 : 128;
        list->entries = (FileEntry *)realloc(list->entries, newcap * sizeof(FileEntry));
        if (!list->entries) { fprintf(stderr, "OOM\n"); exit(1); }
        list->capacity = newcap;
    }
    list->entries[list->count].relpath = strdup(relpath);
    list->entries[list->count].ext = strdup(ext);
    list->entries[list->count].lines = lines;
    list->entries[list->count].chars = chars;
    list->count++;
}

static int compare_entries(const void *a, const void *b) {
    const FileEntry *ea = (const FileEntry *)a;
    const FileEntry *eb = (const FileEntry *)b;
    int cmp = strcmp(ea->ext, eb->ext);
    if (cmp != 0) return cmp;
    return strcmp(ea->relpath, eb->relpath);
}

static char *build_path(const char *prefix, const char *suffix) {
    if (suffix[0] == '\0') {
        return strdup(prefix);
    }
    size_t len = strlen(prefix) + 1 + strlen(suffix) + 1;
    char *p = (char *)malloc(len);
    if (!p) { fprintf(stderr, "OOM\n"); exit(1); }
    snprintf(p, len, "%s/%s", prefix, suffix);
    return p;
}

static void walk(const char *base, const char *rel, FileList *list) {
    char *fullpath = build_path(base, rel);
    DIR *dir = opendir(fullpath);
    if (!dir) { free(fullpath); return; }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char *child_rel;
        if (rel[0] == '\0') {
            child_rel = strdup(entry->d_name);
        } else {
            size_t len = strlen(rel) + 1 + strlen(entry->d_name) + 1;
            child_rel = (char *)malloc(len);
            snprintf(child_rel, len, "%s/%s", rel, entry->d_name);
        }

        char *child_full = build_path(base, child_rel);

        struct stat st;
        if (lstat(child_full, &st) != 0) {
            free(child_rel);
            free(child_full);
            continue;
        }

        if (S_ISLNK(st.st_mode)) {
            free(child_rel);
            free(child_full);
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            walk(base, child_rel, list);
        } else if (S_ISREG(st.st_mode)) {
            long lines = 0, chars = 0;
            FILE *f = fopen(child_full, "rb");
            if (f) {
                int c;
                int last_was_newline = 0;
                int has_content = 0;
                while ((c = fgetc(f)) != EOF) {
                    chars++;
                    has_content = 1;
                    if (c == '\n') {
                        lines++;
                        last_was_newline = 1;
                    } else {
                        last_was_newline = 0;
                    }
                }
                if (has_content && !last_was_newline) lines++;
                fclose(f);
            }

            const char *dot = strrchr(entry->d_name, '.');
            const char *ext;
            if (dot && dot != entry->d_name) {
                ext = dot;
            } else {
                ext = "";
            }

            add_entry(list, child_rel, ext, lines, chars);
        }

        free(child_rel);
        free(child_full);
    }
    closedir(dir);
    free(fullpath);
}

int main(void) {
    const char *base = "<tmp>";

    FileList list = {0};

    walk(base, "", &list);

    qsort(list.entries, list.count, sizeof(FileEntry), compare_entries);

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0, total_lines = 0, total_chars = 0;

    int i = 0;
    while (i < list.count) {
        const char *ext = list.entries[i].ext;
        int j = i;
        long g_lines = 0, g_chars = 0;
        int g_count = 0;
        while (j < list.count && strcmp(list.entries[j].ext, ext) == 0) {
            g_lines += list.entries[j].lines;
            g_chars += list.entries[j].chars;
            g_count++;
            j++;
        }

        printf("Extension: %s\n", ext);
        printf("  Files: %d\n", g_count);
        printf("  Total Lines: %ld\n", g_lines);
        printf("  Total Characters: %ld\n", g_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n",
                   list.entries[k].relpath,
                   list.entries[k].lines,
                   list.entries[k].chars);
        }

        total_files += g_count;
        total_lines += g_lines;
        total_chars += g_chars;

        i = j;
    }

    printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n", total_files, total_lines, total_chars);

    for (int k = 0; k < list.count; k++) {
        free(list.entries[k].relpath);
        free(list.entries[k].ext);
    }
    free(list.entries);

    return 0;
