        while (*s) {
            if (*s == '[') depth++;
            else if (*s == ']') { depth--; if (depth == 0) { s++; break; } }
            else if (*s == '"') { s++; while (*s && *s != '"') { if (*s == '\\') s++; s++; } if (*s == '"') s++; }
            else s++;
        }
    } else {
        double dummy;
        s = parse_number(s, &dummy);
    }
    *sp = s;
}

static void add_edge(Node *nodes, int from, int to, double weight) {
    Edge *e = malloc(sizeof(Edge));
    e->to = to;
    e->weight = weight;
    e->next = nodes[from].head;
    nodes[from].head = e;
}

/* Global for qsort comparison */
static Node *g_nodes = NULL;
static int cmp_order(const void *a, const void *b) {
    int ia = *(const int*)a, ib = *(const int*)b;
    return strcmp(g_nodes[ia].name, g_nodes[ib].name);
}

int main(void) {
    const char *path = "<tmp>";

    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc((size_t)fsize + 1);
    if (!buf) { fclose(f); return 1; }
    size_t rd = fread(buf, 1, (size_t)fsize, f);
    buf[rd] = '\0';
    fclose(f);

    int n_nodes = 0, n_edges = 0;
    char **node_names = NULL;
    char **edge_from = NULL;
    char **edge_to = NULL;
    double *edge_w = NULL;

    const char *p = buf;
    p = skip_ws(p);
    if (*p != '{') { free(buf); return 1; }
    p++;

    while (1) {
        p = skip_ws(p);
        if (*p == '}') { p++; break; }
        if (*p == ',') { p++; continue; }
        if (*p == '\0') break;

        char key[256];
        p = parse_string(p, key, 256);
        if (!p) break;
        p = skip_ws(p);
        if (*p == ':') p++;
        p = skip_ws(p);

        if (strcmp(key, "nodes") == 0) {
            if (*p != '[') { free(buf); return 1; }
            p++;
            const char *tmp = p;
            int cnt = 0;
            while (1) {
                tmp = skip_ws(tmp);
                if (*tmp == ']') { tmp++; break; }
                if (*tmp == ',') { tmp++; continue; }
                if (*tmp == '\0') break;
                char dummy[256];
                tmp = parse_string(tmp, dummy, 256);
                if (!tmp) break;
                cnt++;
            }
            n_nodes = cnt;
            node_names = malloc((size_t)n_nodes * sizeof(char *));
            for (int i = 0; i < n_nodes; i++) {
                p = skip_ws(p);
                if (i > 0) { if (*p == ',') p++; p = skip_ws(p); }
                char *nm = malloc(256);
                p = parse_string(p, nm, 256);
                node_names[i] = nm;
            }
            p = skip_ws(p);
            if (*p == ']') p++;
        } else if (strcmp(key, "edges") == 0) {
            if (*p != '[') { free(buf); return 1; }
            p++;
            const char *tmp = p;
            int cnt = 0;
            while (1) {
                tmp = skip_ws(tmp);
                if (*tmp == ']') { tmp++; break; }
                if (*tmp == ',') { tmp++; continue; }
                if (*tmp == '\0') break;
                if (*tmp == '{') {
                    int depth = 0;
                    while (*tmp) {
                        if (*tmp == '{') depth++;
                        else if (*tmp == '}') { depth--; if (depth == 0) { tmp++; break; } }
                        else if (*tmp == '"') { tmp++; while (*tmp && *tmp != '"') { if (*tmp == '\\') tmp++; tmp++; } if (*tmp == '"') tmp++; }
                        else tmp++;
                    }
                }
                cnt++;
            }
            n_edges = cnt;
            edge_from = malloc((size_t)n_edges * sizeof(char *));
            edge_to = malloc((size_t)n_edges * sizeof(char *));
            edge_w = malloc((size_t)n_edges * sizeof(double));

            for (int i = 0; i < n_edges; i++) {
                p = skip_ws(p);
                if (i > 0) { if (*p == ',') p++; p = skip_ws(p); }
                if (*p != '{') { free(buf); return 1; }
                p++;
                while (1) {
                    p = skip_ws(p);
                    if (*p == '}') { p++; break; }
                    if (*p == ',') { p++; continue; }
                    if (*p == '\0') break;
                    char fk[256];
                    p = parse_string(p, fk, 256);
                    if (!p) break;
                    p = skip_ws(p);
                    if (*p == ':') p++;
                    p = skip_ws(p);
                    if (strcmp(fk, "from") == 0) {
                        char *s = malloc(256);
                        p = parse_string(p, s, 256);
                        edge_from[i] = s;
                    } else if (strcmp(fk, "to") == 0) {
                        char *s = malloc(256);
                        p = parse_string(p, s, 256);
                        edge_to[i] = s;
                    } else if (strcmp(fk, "weight") == 0) {
                        p = parse_number(p, &edge_w[i]);
                    } else {
                        skip_value(&p);
                    }
                }
            }
            p = skip_ws(p);
            if (*p == ']') p++;
        } else {
            skip_value(&p);
        }
    }

    /* Build graph */
    Node *nodes = malloc((size_t)n_nodes * sizeof(Node));
    for (int i = 0; i < n_nodes; i++) {
        nodes[i].name = node_names[i];
        nodes[i].head = NULL;
    }

    /* Hash map for O(1) node lookup */
    HashMap hm;
    hashmap_init(&hm, n_nodes);
    for (int i = 0; i < n_nodes; i++) {
        hashmap_insert(&hm, node_names[i], i);
    }

    for (int i = 0; i < n_edges; i++) {
        int from = hashmap_get(&hm, edge_from[i]);
        int to = hashmap_get(&hm, edge_to[i]);
        if (from >= 0 && to >= 0) {
            add_edge(nodes, from, to, edge_w[i]);
            add_edge(nodes, to, from, edge_w[i]);
        }
    }

    /* Dijkstra from "A" using min-heap */
    int src = hashmap_get(&hm, "A");
    if (src < 0) {
        fprintf(stderr, "Node A not found\n");
        free(buf);
        return 1;
    }

    double *dist = malloc((size_t)n_nodes * sizeof(double));
    int *visited = malloc((size_t)n_nodes * sizeof(int));
    for (int i = 0; i < n_nodes; i++) {
        dist[i] = INFINITY;
        visited[i] = 0;
    }
    dist[src] = 0.0;

    MinHeap heap;
    heap.cap = n_nodes + 1;
    heap.idx = malloc((size_t)heap.cap * sizeof(int));
    heap.key = malloc((size_t)heap.cap * sizeof(double));
    heap.size = 0;
    heap_push(&heap, src, 0.0);

    while (heap.size > 0) {
        double d;
        int u = heap_pop(&heap, &d);
        if (visited[u]) continue;
        visited[u] = 1;

        Edge *e = nodes[u].head;
        while (e) {
            if (!visited[e->to]) {
                double nd = dist[u] + e->weight;
                if (nd < dist[e->to]) {
                    dist[e->to] = nd;
                    heap_push(&heap, e->to, nd);
                }
            }
            e = e->next;
        }
    }

    /* Sort node indices alphabetically using qsort */
    int *order = malloc((size_t)n_nodes * sizeof(int));
    for (int i = 0; i < n_nodes; i++) order[i] = i;
    g_nodes = nodes;
    qsort(order, (size_t)n_nodes, sizeof(int), cmp_order);

    /* Output */
    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < n_nodes; i++) {
        int idx = order[i];
        printf("A -> %s: ", nodes[idx].name);
        if (dist[idx] == INFINITY) {
            printf("unreachable");
        } else if (dist[idx] == (double)(long long)dist[idx]) {
            printf("%lld", (long long)dist[idx]);
        } else {
            printf("%g", dist[idx]);
        }
        printf("\n");
    }

    /* Cleanup */
    free(buf);
    free(dist);
    free(visited);
    free(order);
    free(heap.idx);
    free(heap.key);
    for (int i = 0; i < n_nodes; i++) {
        Edge *e = nodes[i].head;
        while (e) { Edge *nx = e->next; free(e); e = nx; }
        free(node_names[i]);
    }
    free(nodes);
    free(node_names);
    for (int i = 0; i < n_edges; i++) { free(edge_from[i]); free(edge_to[i]); }
    free(edge_from);
    free(edge_to);
    free(edge_w);
    free(hm.keys);
    free(hm.vals);
    free(hm.used);

    return 0;
}
